export default Register;

import React, { useState, useEffect } from 'react';
import MainLayout from '../../components/layout/MainLayout';
import { useAuth } from '../../context/AuthContext';
import automationService from '../../services/automationService';
import type { WorkflowRuleDTO, CreateWorkflowRuleDTO, IntegrationSettingsDTO } from '../../services/automationService';

const Automation: React.FC = () => {
  const { user } = useAuth();
  const [rules, setRules] = useState<WorkflowRuleDTO[]>([]);
  const [settings, setSettings] = useState<IntegrationSettingsDTO | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formData, setFormData] = useState<CreateWorkflowRuleDTO>({ ruleName: '', triggerEvent: 'New Lead', condition: '', action: 'Assign Lead', isActive: true });

  const isSuperAdmin = user?.role === 'SuperAdmin';
  const isManager    = isSuperAdmin || user?.role === 'Marketing Manager';

  useEffect(() => { fetchData(); }, []);
  const fetchData = async () => {
    try {
      const r = await automationService.getRules(); setRules(r);
      if (isSuperAdmin) { const s = await automationService.getSettings(); setSettings(s); }
    } catch (_) { console.error("Failed to fetch automation data"); }
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault(); setIsSubmitting(true);
    try { await automationService.createRule(formData); setIsModalOpen(false); fetchData(); }
    catch (_) { console.error("Error saving data"); } finally { setIsSubmitting(false); }
  };

  const handleToggle = async (id: number) => {
    try { await automationService.toggleRule(id); setRules(rules.map(r => r.ruleID === id ? { ...r, isActive: !r.isActive } : r)); }
    catch (_) { console.error("Error toggling status"); }
  };

  const handleDelete = async (id: number) => {
    if (!confirm('Delete this rule?')) return;
    try { await automationService.deleteRule(id); fetchData(); } catch (_) { console.error("Failed to delete rule"); }
  };

  return (
    <MainLayout>
      <div className="page-header anim-slide-up">
        <div className="page-header-left">
          <div className="eyebrow">Operations</div>
          <h1>Workflow & Automation</h1>
          <p>Automate tasks and manage system integrations.</p>
        </div>
        {isManager && <button className="btn btn-primary" onClick={() => setIsModalOpen(true)}>+ New Rule</button>}
      </div>

      <div className="grid-2 anim-slide-up delay-1" style={{ alignItems: "start" }}>
        {/* Rules */}
        <div>
          <p className="section-label">Automation Rules</p>
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {rules.map(rule => (
              <div key={rule.ruleID} className="card" style={{ padding: "16px", opacity: rule.isActive ? 1 : 0.5 }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: "10px" }}>
                  <div>
                    <div style={{ fontSize: "13px", fontWeight: "700", color: "var(--text-primary)" }}>{rule.ruleName}</div>
                    <div style={{ fontSize: "10px", color: "#a78bfa", fontWeight: "700", textTransform: "uppercase", letterSpacing: "0.06em", marginTop: "2px" }}>{rule.triggerEvent}</div>
                  </div>
                  <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                    <button className={`toggle ${rule.isActive ? 'on' : 'off'}`} onClick={() => handleToggle(rule.ruleID)}>
                      <div className="toggle-thumb" />
                    </button>
                    {isManager && <button onClick={() => handleDelete(rule.ruleID)} style={{ background: "none", border: "none", color: "var(--text-muted)", cursor: "pointer", padding: "2px", fontSize: "13px", transition: "color 0.15s" }}
                      onMouseEnter={e => (e.currentTarget as HTMLElement).style.color = "#f87171"}
                      onMouseLeave={e => (e.currentTarget as HTMLElement).style.color = "var(--text-muted)"}>
                      🗑
                    </button>}
                  </div>
                </div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px", paddingTop: "10px", borderTop: "1px solid var(--border)" }}>
                  <div>
                    <div style={{ fontSize: "9px", fontWeight: "700", textTransform: "uppercase", color: "var(--text-muted)", marginBottom: "3px" }}>Condition</div>
                    <div style={{ fontSize: "12px", color: "var(--text-secondary)" }}>{rule.condition || '—'}</div>
                  </div>
                  <div>
                    <div style={{ fontSize: "9px", fontWeight: "700", textTransform: "uppercase", color: "var(--text-muted)", marginBottom: "3px" }}>Action</div>
                    <div style={{ fontSize: "12px", fontWeight: "600", color: "var(--text-primary)" }}>{rule.action}</div>
                  </div>
                </div>
              </div>
            ))}
            {rules.length === 0 && (
              <div className="card" style={{ padding: "36px", textAlign: "center" }}>
                <div style={{ fontSize: "28px", marginBottom: "8px" }}>⚙</div>
                <div style={{ fontSize: "13px", color: "var(--text-muted)" }}>No rules configured.</div>
              </div>
            )}
          </div>
        </div>

        {/* Integrations (SuperAdmin only) */}
        {isSuperAdmin && (
          <div>
            <p className="section-label">System Integrations</p>
            <div className="card" style={{ padding: "20px", marginBottom: "12px" }}>
              <div style={{ marginBottom: "18px" }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "8px" }}>
                  <label style={{ margin: 0, fontSize: "12px", fontWeight: "600", color: "var(--text-secondary)" }}>Mapbox Access Token</label>
                  <span className="badge badge-green">CONNECTED</span>
                </div>
                <input type="password" readOnly value={settings?.mapboxAccessToken ?? ''} style={{ fontFamily: "monospace", fontSize: "12px" }} />
              </div>
              <div style={{ marginBottom: "18px" }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "10px" }}>
                  <label style={{ margin: 0, fontSize: "12px", fontWeight: "600", color: "var(--text-secondary)" }}>Email Service (SMTP)</label>
                  <span className="badge badge-green">ACTIVE</span>
                </div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px", marginBottom: "10px" }}>
                  <div>
                    <div style={{ fontSize: "9px", fontWeight: "700", textTransform: "uppercase", color: "var(--text-muted)", marginBottom: "3px" }}>Host</div>
                    <div style={{ fontSize: "12px", color: "var(--text-primary)" }}>{settings?.emailSmtpHost}</div>
                  </div>
                  <div>
                    <div style={{ fontSize: "9px", fontWeight: "700", textTransform: "uppercase", color: "var(--text-muted)", marginBottom: "3px" }}>Port</div>
                    <div style={{ fontSize: "12px", color: "var(--text-primary)" }}>{settings?.emailSmtpPort}</div>
                  </div>
                </div>
                <div>
                  <div style={{ fontSize: "9px", fontWeight: "700", textTransform: "uppercase", color: "var(--text-muted)", marginBottom: "3px" }}>Sender</div>
                  <div style={{ fontSize: "12px", color: "var(--text-primary)" }}>{settings?.emailSender}</div>
                </div>
              </div>
              <button className="btn btn-ghost" style={{ width: "100%", justifyContent: "center" }}>Configure Integrations</button>
            </div>

            <div style={{ background: "var(--accent-soft)", border: "1px solid var(--border-accent)", borderRadius: "10px", padding: "14px 16px", display: "flex", gap: "10px" }}>
              <div style={{ fontSize: "20px" }}>🛡</div>
              <div>
                <div style={{ fontSize: "12px", fontWeight: "700", color: "#c4b5fd", marginBottom: "3px" }}>Admin Security</div>
                <div style={{ fontSize: "11px", color: "var(--text-muted)", lineHeight: 1.5 }}>Integration settings are only visible to SuperAdmins. Marketing Managers can manage rules but cannot view API keys or SMTP credentials.</div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Modal */}
      {isModalOpen && (
        <div className="modal-overlay">
          <div className="modal-box" style={{ maxWidth: "440px" }}>
            <div className="modal-header">
              <h2>Create Rule</h2>
              <button className="modal-close-btn" onClick={() => setIsModalOpen(false)}>✕</button>
            </div>
            <form onSubmit={handleCreate}>
              <div className="form-group"><label>Rule Name</label><input required value={formData.ruleName} onChange={e => setFormData(f => ({ ...f, ruleName: e.target.value }))} placeholder="e.g., Welcome Email" /></div>
              <div className="grid-2">
                <div className="form-group">
                  <label>Trigger</label>
                  <select value={formData.triggerEvent} onChange={e => setFormData(f => ({ ...f, triggerEvent: e.target.value }))}>
                    {['New Lead', 'Email Opened', 'Lead Status Changed'].map(o => <option key={o} className="bg-slate-900">{o}</option>)}
                  </select>
                </div>
                <div className="form-group">
                  <label>Action</label>
                  <select value={formData.action} onChange={e => setFormData(f => ({ ...f, action: e.target.value }))}>
                    {['Assign Lead', 'Send Email', 'Update Score'].map(o => <option key={o} className="bg-slate-900">{o}</option>)}
                  </select>
                </div>
              </div>
              <div className="form-group"><label>Condition (JSON or text)</label><textarea style={{ height: "70px", resize: "none", fontFamily: "monospace", fontSize: "12px" }} value={formData.condition} onChange={e => setFormData(f => ({ ...f, condition: e.target.value }))} placeholder='{"score_gt": 50}' /></div>
              <div className="modal-footer">
                <button type="button" className="btn btn-ghost" onClick={() => setIsModalOpen(false)}>Cancel</button>
                <button type="submit" className="btn btn-primary" disabled={isSubmitting}>{isSubmitting ? 'Saving…' : 'Create Rule'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </MainLayout>
  );
};

export default Automation;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import MainLayout from '../../components/layout/MainLayout';
import campaignService from '../../services/campaignService';
import type { CampaignDTO } from '../../services/campaignService';
import MapboxMap from '../../components/common/MapboxMap';

const CampaignDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [campaign, setCampaign] = useState<CampaignDTO | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchCampaign = async () => {
      try {
        if (id) {
          const data = await campaignService.getCampaign(parseInt(id));
          setCampaign(data);
        }
      } catch (_) {
        console.error("Failed to fetch campaign details");
      } finally {
        setLoading(false);
      }
    };
    fetchCampaign();
  }, [id]);

  if (loading) return (
    <MainLayout>
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="w-10 h-10 border-4 border-purple-500 border-t-transparent rounded-full animate-spin"></div>
      </div>
    </MainLayout>
  );

  if (!campaign) return (
    <MainLayout>
      <div className="text-center py-20">
        <h2 className="text-2xl font-bold text-white">Campaign not found</h2>
        <button className="btn btn-primary mt-4" onClick={() => navigate('/campaigns')}>Back to Campaigns</button>
      </div>
    </MainLayout>
  );

  return (
    <MainLayout>
      <div className="page-header anim-slide-up">
        <div className="page-header-left">
          <div className="eyebrow">Marketing / Campaigns</div>
          <h1>{campaign.campaignName}</h1>
          <p>{campaign.description}</p>
        </div>
        <div className="flex gap-3">
          <button className="btn btn-ghost" onClick={() => navigate('/campaigns')}>← Back</button>
          <button className="btn btn-primary">Edit Campaign</button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 anim-slide-up delay-1">
        {/* Left Column: Details */}
        <div className="space-y-6">
          <div className="card p-6">
            <h3 className="text-sm font-bold text-slate-500 uppercase tracking-widest mb-4">Quick Stats</h3>
            <div className="space-y-4">
              <div className="flex justify-between items-center">
                <span className="text-slate-400">Status</span>
                <span className={`badge ${campaign.status === 'Active' ? 'badge-green' : 'badge-amber'}`}>{campaign.status}</span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-slate-400">Budget</span>
                <span className="text-white font-bold">₱{campaign.budget.toLocaleString()}</span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-slate-400">Destination</span>
                <span className="text-purple-300 font-medium">{campaign.locationName}</span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-slate-400">Target Goal</span>
                <span className="text-slate-200">{campaign.targetGoal}</span>
              </div>
            </div>
          </div>

          <div className="card p-6">
            <h3 className="text-sm font-bold text-slate-500 uppercase tracking-widest mb-4">Timeline</h3>
            <div className="space-y-3">
              <div>
                <div className="text-[10px] text-slate-500 font-bold uppercase">Starts</div>
                <div className="text-slate-200">{new Date(campaign.startDate).toLocaleDateString()}</div>
              </div>
              <div>
                <div className="text-[10px] text-slate-500 font-bold uppercase">Ends</div>
                <div className="text-slate-200">{new Date(campaign.endDate).toLocaleDateString()}</div>
              </div>
            </div>
          </div>
        </div>

        {/* Right Column: Map */}
        <div className="lg:col-span-2 space-y-6">
          <div className="card p-2 h-full min-h-[500px] flex flex-col">
            <div className="p-4 border-b border-white/5 flex justify-between items-center">
              <h3 className="font-bold text-white flex items-center gap-2">
                <span className="text-purple-400">📍</span> Destination Map
              </h3>
              <span className="text-[10px] bg-purple-500/10 text-purple-300 px-2 py-1 rounded border border-purple-500/20">LIVE INTEL</span>
            </div>
            <div className="flex-1 p-2">
              {campaign.latitude && campaign.longitude ? (
                <MapboxMap 
                  lat={Number(campaign.latitude)} 
                  lng={Number(campaign.longitude)} 
                  title={campaign.locationName || campaign.campaignName}
                  description={campaign.description}
                  showRoute={true}
                />
              ) : (
                <div className="w-full h-full flex flex-col items-center justify-center bg-slate-900/50 rounded-xl text-slate-500 italic p-10 text-center">
                  <div className="text-4xl mb-3">📡</div>
                  Location coordinates unavailable for this campaign.
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </MainLayout>
  );
};

export default CampaignDetails;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import MainLayout from '../../components/layout/MainLayout';
import { useAuth } from '../../context/AuthContext';
import campaignService from '../../services/campaignService';
import type { CampaignDTO } from '../../services/campaignService';
import MapboxMap from '../../components/common/MapboxMap';

const statusColor: Record<string, string> = {
  Draft:     'badge badge-gray',
  Active:    'badge badge-green',
  Paused:    'badge badge-amber',
  Completed: 'badge badge-blue',
  Archived:  'badge badge-red',
};

const Campaigns: React.FC = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [campaigns, setCampaigns] = useState<CampaignDTO[]>([]);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [sortKey, setSortKey] = useState<keyof CampaignDTO>('campaignName');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('asc');
  const [page, setPage] = useState(1);
  const pageSize = 5;
  const [loading, setLoading] = useState(true);

  const isManager = user?.role === 'SuperAdmin' || user?.role === 'Marketing Manager';

  useEffect(() => {
    fetchData();
  }, [statusFilter, search]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const data = await campaignService.getCampaigns({ status: statusFilter, search });
      setCampaigns(data);
    } catch (_) {
      console.error("Failed to fetch campaigns");
    } finally {
      setLoading(false);
    }
  };

  const sorted = [...campaigns].sort((a, b) => {
    const valA = a[sortKey] ?? '';
    const valB = b[sortKey] ?? '';
    if (valA < valB) return sortOrder === 'asc' ? -1 : 1;
    if (valA > valB) return sortOrder === 'asc' ? 1 : -1;
    return 0;
  });

  const paginated = sorted.slice((page - 1) * pageSize, page * pageSize);
  const totalPages = Math.ceil(sorted.length / pageSize);

  return (
    <MainLayout>
      <div className="page-header anim-slide-up">
        <div className="page-header-left">
          <div className="eyebrow">Marketing</div>
          <h1>Campaigns</h1>
          <p>Manage and track your global marketing initiatives.</p>
        </div>
        {isManager && <button className="btn btn-primary" onClick={() => navigate('/campaigns/new')}>+ New Campaign</button>}
      </div>

      <div className="filter-bar anim-fade-in text-slate-300">
        <input placeholder="Search campaigns..." value={search} onChange={e => { setSearch(e.target.value); setPage(1); }} />
        <select value={statusFilter} onChange={e => { setStatusFilter(e.target.value); setPage(1); }}>
          <option value="">All Statuses</option>
          {['Draft', 'Active', 'Paused', 'Completed', 'Archived'].map(s => <option key={s} value={s}>{s}</option>)}
        </select>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 card overflow-hidden anim-slide-up delay-1">
          <div className="tbl-header">
            <span>Global Campaigns</span>
            <small>{sorted.length} active</small>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="tbl-head-row">
                  <th className="tbl-cell cursor-pointer" onClick={() => { setSortKey('campaignName'); setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc'); }}>Campaign</th>
                  <th className="tbl-cell">Status</th>
                  <th className="tbl-cell text-right">Budget</th>
                </tr>
              </thead>
              <tbody>
                {loading ? (
                  <tr><td colSpan={3} className="p-8 text-center text-slate-500">Loading...</td></tr>
                ) : paginated.map(c => (
                  <tr key={c.campaignID} className="tbl-row group">
                    <td className="tbl-cell">
                      <div className="font-bold text-white cursor-pointer hover:text-purple-400 transition-colors" onClick={() => navigate(`/campaigns/${c.campaignID}`)}>
                        {c.campaignName}
                      </div>
                      <div className="text-[10px] text-slate-500">{c.locationName}</div>
                    </td>
                    <td className="tbl-cell"><span className={statusColor[c.status]}>{c.status}</span></td>
                    <td className="tbl-cell text-right text-sm text-slate-300">${c.budget.toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="p-4 border-t border-white/5 flex flex-col sm:flex-row gap-3 sm:gap-0 justify-between sm:items-center text-[11px] text-slate-400">
             <div>Page {page} of {totalPages || 1}</div>
             <div className="flex gap-2">
               <button disabled={page === 1} onClick={() => setPage(p => p - 1)} className="btn btn-ghost py-1 px-3">Prev</button>
               <button disabled={page >= totalPages} onClick={() => setPage(p => p + 1)} className="btn btn-ghost py-1 px-3">Next</button>
             </div>
          </div>
        </div>

        <div className="card h-full min-h-[400px] overflow-hidden hidden lg:block anim-slide-up delay-2">
          {paginated.length > 0 && paginated[0].latitude ? (
            <MapboxMap lat={Number(paginated[0].latitude)} lng={Number(paginated[0].longitude)} title={paginated[0].campaignName} showRoute={false} />
          ) : (
            <div className="w-full h-full flex items-center justify-center bg-slate-900/50 italic text-slate-600">Map Preview</div>
          )}
        </div>
      </div>
    </MainLayout>
  );
};

export default Campaigns;

import React, { useState, useEffect } from 'react';
import MainLayout from '../../components/layout/MainLayout';
import { useAuth } from '../../context/AuthContext';
import emailService from '../../services/emailService';
import type { EmailTemplateDTO, CreateEmailTemplateDTO, EmailLogDTO } from '../../services/emailService';
import campaignService from '../../services/campaignService';
import type { CampaignDTO } from '../../services/campaignService';
import leadService from '../../services/leadService';
import type { LeadDTO } from '../../services/leadService';

const EmailMarketing: React.FC = () => {
  const { user } = useAuth();
  const [templates, setTemplates] = useState<EmailTemplateDTO[]>([]);
  const [logs, setLogs] = useState<EmailLogDTO[]>([]);
  const [campaigns, setCampaigns] = useState<CampaignDTO[]>([]);
  const [leads, setLeads] = useState<LeadDTO[]>([]);
  const [isTemplateModalOpen, setIsTemplateModalOpen] = useState(false);
  const [isSendModalOpen, setIsSendModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [templateData, setTemplateData] = useState<CreateEmailTemplateDTO>({ templateName: '', subject: '', body: '' });
  const [sendData, setSendData] = useState({ campaignID: 0, templateID: 0 });

  const isManager = user?.role === 'SuperAdmin' || user?.role === 'Marketing Manager';

  useEffect(() => { fetchData(); }, []);

  const fetchData = async () => {
    try {
      const [td, ld, cd, led] = await Promise.all([
        emailService.getTemplates(), emailService.getLogs(),
        campaignService.getCampaigns(), leadService.getLeads()
      ]);
      setTemplates(td); setLogs(ld); setCampaigns(cd); setLeads(led);
      if (cd.length > 0) setSendData(s => ({ ...s, campaignID: cd[0].campaignID }));
      if (td.length > 0) setSendData(s => ({ ...s, templateID: td[0].templateID }));
    } catch (_) { console.error("Error fetching data"); }
  };

  const handleCreateTemplate = async (e: React.FormEvent) => {
    e.preventDefault(); setIsSubmitting(true);
    try { await emailService.createTemplate(templateData); setIsTemplateModalOpen(false); fetchData(); }
    catch (_) { console.error("Error occurred"); } finally { setIsSubmitting(false); }
  };

  const handleApprove = async (id: number, status: string) => {
    try {
      await emailService.approveTemplate(id, status);
      fetchData();
    } catch (_) { console.error("Error fetching data"); }
  };

  const handleBulkSend = async () => {
    setIsSubmitting(true);
    try {
      await emailService.bulkSend({ campaignID: sendData.campaignID, templateID: sendData.templateID, leadIDs: leads.filter(l => l.campaignID === sendData.campaignID).map(l => l.leadID) });
      setIsSendModalOpen(false); fetchData();
    } catch (_) { console.error("Error occurred"); } finally { setIsSubmitting(false); }
  };

  const statusClass: Record<string, string> = { Sent: 'badge badge-green', Failed: 'badge badge-red', Pending: 'badge badge-amber' };

  return (
    <MainLayout>
      {/* Header */}
      <div className="page-header anim-slide-up">
        <div className="page-header-left">
          <div className="eyebrow">Communications</div>
          <h1>Email Marketing</h1>
          <p>Design templates and reach your prospects at scale.</p>
        </div>
        <div className="flex flex-wrap gap-2 w-full sm:w-auto">
          {isManager && (
            <button className="btn btn-ghost" onClick={() => setIsTemplateModalOpen(true)}>+ New Template</button>
          )}
          <button className="btn btn-primary" onClick={() => setIsSendModalOpen(true)}>🚀 Bulk Send</button>
        </div>
      </div>

      {/* Templates grid */}
      <p className="section-label anim-fade-in">Email Templates</p>
      <div className="grid-3 anim-slide-up delay-1" style={{ marginBottom: "24px" }}>
        {templates.map(t => (
          <div key={t.templateID} className="card" style={{ padding: "18px" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: "12px" }}>
              <div style={{
                width: "38px", height: "38px", borderRadius: "9px",
                background: "var(--accent-soft)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "18px"
              }}>📄</div>
              <span className={t.isApproved === 'Approved' ? 'badge badge-green' : 'badge badge-amber'}>{t.isApproved}</span>
            </div>
            <div style={{ fontSize: "13px", fontWeight: "700", color: "var(--text-primary)", marginBottom: "3px" }}>{t.templateName}</div>
            <div style={{ fontSize: "11px", color: "var(--text-muted)", marginBottom: "14px", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{t.subject}</div>
            
            {/* Admin Approval Actions */}
            {(user?.role === 'SuperAdmin' || user?.role === 'Admin') && t.isApproved === 'Pending' && (
              <div style={{ display: "flex", gap: "6px", marginBottom: "12px" }}>
                <button className="btn btn-primary" style={{ flex: 1, padding: "5px", fontSize: "10px" }} onClick={() => handleApprove(t.templateID, 'Approved')}>Approve</button>
                <button className="btn btn-danger" style={{ flex: 1, padding: "5px", fontSize: "10px" }} onClick={() => handleApprove(t.templateID, 'Rejected')}>Reject</button>
              </div>
            )}

            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", paddingTop: "12px", borderTop: "1px solid var(--border)" }}>
              <span style={{ fontSize: "10px", color: "var(--text-muted)" }}>By {t.creatorName}</span>
              <button className="btn btn-ghost" style={{ padding: "4px 10px", fontSize: "11px" }}>Edit</button>
            </div>
          </div>
        ))}
        {templates.length === 0 && (
          <div className="card" style={{ padding: "36px", textAlign: "center", gridColumn: "1/-1" }}>
            <div style={{ fontSize: "28px", marginBottom: "8px" }}>📭</div>
            <div style={{ fontSize: "13px", color: "var(--text-muted)" }}>No templates yet. Create your first one!</div>
          </div>
        )}
      </div>

      {/* Logs table */}
      <div className="card overflow-hidden anim-slide-up delay-2">
        <div className="tbl-header">
          <span>Recent Email Activity</span>
          <small>{logs.length} records</small>
        </div>
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr className="tbl-head-row">
                <th className="tbl-cell">Recipient</th>
                <th className="tbl-cell">Template</th>
                <th className="tbl-cell">Campaign</th>
                <th className="tbl-cell">Status</th>
                <th className="tbl-cell">Sent</th>
              </tr>
            </thead>
            <tbody>
              {logs.map(log => (
                <tr key={log.emailLogID} className="tbl-row">
                  <td className="tbl-cell" style={{ fontSize: "13px", fontWeight: "600", color: "var(--text-primary)" }}>{log.leadName}</td>
                  <td className="tbl-cell" style={{ fontSize: "12px", color: "var(--text-secondary)" }}>{log.templateName}</td>
                  <td className="tbl-cell" style={{ fontSize: "12px", color: "var(--text-secondary)" }}>{log.campaignName}</td>
                  <td className="tbl-cell"><span className={statusClass[log.status] ?? 'badge badge-gray'}>{log.status}</span></td>
                  <td className="tbl-cell" style={{ fontSize: "11px", color: "var(--text-muted)" }}>{new Date(log.sentDate).toLocaleString()}</td>
                </tr>
              ))}
              {logs.length === 0 && (
                <tr><td colSpan={5}>
                  <div className="empty-state">
                    <div className="empty-icon">📧</div>
                    <h3>No emails sent yet</h3>
                    <p>Use Bulk Send to launch your first campaign.</p>
                  </div>
                </td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Create Template Modal */}
      {isTemplateModalOpen && (
        <div className="modal-overlay">
          <div className="modal-box" style={{ maxWidth: "520px" }}>
            <div className="modal-header">
              <h2>Create Email Template</h2>
              <button className="modal-close-btn" onClick={() => setIsTemplateModalOpen(false)}>✕</button>
            </div>
            <form onSubmit={handleCreateTemplate}>
              <div className="form-group"><label>Template Name</label><input required value={templateData.templateName} onChange={e => setTemplateData(t => ({ ...t, templateName: e.target.value }))} /></div>
              <div className="form-group"><label>Subject</label><input required value={templateData.subject} onChange={e => setTemplateData(t => ({ ...t, subject: e.target.value }))} /></div>
              <div className="form-group"><label>HTML Body</label><textarea required style={{ height: "140px", resize: "none", fontFamily: "monospace", fontSize: "12px" }} value={templateData.body} onChange={e => setTemplateData(t => ({ ...t, body: e.target.value }))} placeholder="<p>Hello!</p>" /></div>
              <div className="modal-footer">
                <button type="button" className="btn btn-ghost" onClick={() => setIsTemplateModalOpen(false)}>Cancel</button>
                <button type="submit" className="btn btn-primary" disabled={isSubmitting}>{isSubmitting ? 'Saving…' : 'Save Template'}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Bulk Send Modal */}
      {isSendModalOpen && (
        <div className="modal-overlay">
          <div className="modal-box" style={{ maxWidth: "400px" }}>
            <div className="modal-header">
              <h2>Bulk Email Launch</h2>
              <button className="modal-close-btn" onClick={() => setIsSendModalOpen(false)}>✕</button>
            </div>
            <div className="form-group"><label>Campaign</label>
              <select value={sendData.campaignID} onChange={e => setSendData(s => ({ ...s, campaignID: parseInt(e.target.value) }))}>
                {campaigns.map(c => <option key={c.campaignID} value={c.campaignID} className="bg-slate-900">{c.campaignName}</option>)}
              </select>
            </div>
            <div className="form-group"><label>Template</label>
              <select value={sendData.templateID} onChange={e => setSendData(s => ({ ...s, templateID: parseInt(e.target.value) }))}>
                {templates.filter(t => t.isApproved === 'Approved').map(t => <option key={t.templateID} value={t.templateID} className="bg-slate-900">{t.templateName}</option>)}
              </select>
            </div>
            <div style={{ background: "var(--accent-soft)", border: "1px solid var(--border-accent)", borderRadius: "9px", padding: "12px 14px", fontSize: "12px", color: "var(--text-secondary)", marginBottom: "8px" }}>
              Target: <span style={{ color: "#a78bfa", fontWeight: "700" }}>{leads.filter(l => l.campaignID === sendData.campaignID).length} leads</span> in selected campaign
            </div>
            <div className="modal-footer">
              <button type="button" className="btn btn-ghost" onClick={() => setIsSendModalOpen(false)}>Cancel</button>
              <button className="btn btn-primary" onClick={handleBulkSend} disabled={isSubmitting || leads.filter(l => l.campaignID === sendData.campaignID).length === 0}>
                {isSubmitting ? 'Launching…' : '🚀 Launch'}
              </button>
            </div>
          </div>
        </div>
      )}
    </MainLayout>
  );
};

export default EmailMarketing;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import MainLayout from '../../components/layout/MainLayout';
import { useAuth } from '../../context/AuthContext';
import leadService from '../../services/leadService';
import type { LeadDTO, CreateLeadDTO } from '../../services/leadService';
import campaignService from '../../services/campaignService';
import type { CampaignDTO } from '../../services/campaignService';

const statusClass: Record<string, string> = {
  New:       'badge badge-blue',
  Contacted: 'badge badge-amber',
  Qualified: 'badge badge-purple',
  Converted: 'badge badge-green',
  Lost:      'badge badge-red',
};

const Leads: React.FC = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [leads, setLeads] = useState<LeadDTO[]>([]);
  const [campaigns, setCampaigns] = useState<CampaignDTO[]>([]);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [sourceFilter, setSourceFilter] = useState('');
  const [sortKey, setSortKey] = useState<keyof LeadDTO>('userName');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('asc');
  const [page, setPage] = useState(1);
  const pageSize = 10;
  
  const [selected, setSelected] = useState<LeadDTO | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [editingLead, setEditingLead] = useState<LeadDTO | null>(null);
  const [formData, setFormData] = useState<CreateLeadDTO>({ campaignID: 0, leadStatus: 'New', leadScore: 0, source: '', notes: '' });

  const isManager = user?.role === 'SuperAdmin' || user?.role === 'Marketing Manager';
  const canModify = isManager || user?.role === 'Marketing Staff';

  useEffect(() => { fetchLeads(); fetchCampaigns(); }, [statusFilter, sourceFilter]);

  const fetchLeads = async () => {
    try { setLeads(await leadService.getLeads({ status: statusFilter, source: sourceFilter, search })); }
    catch (_) { console.error("Error occurred"); }
  };

  const fetchCampaigns = async () => {
    try {
      const data = await campaignService.getCampaigns();
      setCampaigns(data);
      if (data.length > 0) setFormData(f => ({ ...f, campaignID: data[0].campaignID }));
    } catch (_) { console.error("Error fetching data"); }
  };

  const sorted = [...leads].sort((a, b) => {
    const valA = (a[sortKey] ?? '').toString().toLowerCase();
    const valB = (b[sortKey] ?? '').toString().toLowerCase();
    if (valA < valB) return sortOrder === 'asc' ? -1 : 1;
    if (valA > valB) return sortOrder === 'asc' ? 1 : -1;
    return 0;
  });

  const paginated = sorted.slice((page - 1) * pageSize, page * pageSize);
  const totalPages = Math.ceil(sorted.length / pageSize);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault(); setIsSubmitting(true);
    try { await leadService.createLead(formData); setIsModalOpen(false); fetchLeads(); }
    catch (_) { console.error("Error occurred"); } finally { setIsSubmitting(false); }
  };

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingLead) return;
    setIsSubmitting(true);
    try {
      await leadService.updateLead(editingLead.leadID, {
        leadStatus: editingLead.leadStatus,
        leadScore: editingLead.leadScore,
        notes: editingLead.notes,
        source: editingLead.source
      });
      setIsEditModalOpen(false);
      fetchLeads();
    } catch (_) { console.error("Error occurred"); } finally { setIsSubmitting(false); }
  };

  const handleDelete = async (id: number) => {
    if (!confirm('Delete this lead?')) return;
    try { await leadService.deleteLead(id); fetchLeads(); } catch (_) { console.error("Error occurred"); }
  };

  return (
    <MainLayout>
      <div className="page-header anim-slide-up">
        <div className="page-header-left">
          <div className="eyebrow">CRM</div>
          <h1>Lead Management</h1>
          <p>Track and convert your potential customers.</p>
        </div>
        {canModify && <button className="btn btn-primary" onClick={() => setIsModalOpen(true)}>+ Add Lead</button>}
      </div>

      <div className="filter-bar anim-fade-in text-slate-300">
        <input placeholder="Search..." value={search} onChange={e => setSearch(e.target.value)} onKeyDown={e => e.key === 'Enter' && fetchLeads()} />
        <select value={statusFilter} onChange={e => { setStatusFilter(e.target.value); setPage(1); }}>
          <option value="">All Statuses</option>
          {['New', 'Contacted', 'Qualified', 'Converted', 'Lost'].map(s => <option key={s} className="bg-slate-900">{s}</option>)}
        </select>
        <select value={sourceFilter} onChange={e => { setSourceFilter(e.target.value); setPage(1); }}>
          <option value="">All Sources</option>
          {['Website', 'Referral', 'Social Media', 'Direct'].map(s => <option key={s} className="bg-slate-900">{s}</option>)}
        </select>
      </div>

      <div className="flex gap-4 items-start">
        <div className="card overflow-hidden flex-1 anim-slide-up delay-1">
          <div className="tbl-header">
            <span>All Leads</span>
            <small>{sorted.length} total</small>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full border-collapse">
              <thead>
                <tr className="tbl-head-row">
                  <th className="tbl-cell cursor-pointer" onClick={() => { setSortKey('userName'); setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc'); }}>Lead</th>
                  <th className="tbl-cell cursor-pointer" onClick={() => { setSortKey('leadStatus'); setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc'); }}>Status</th>
                  <th className="tbl-cell cursor-pointer" onClick={() => { setSortKey('leadScore'); setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc'); }}>Score</th>
                  <th className="tbl-cell" style={{ textAlign: "right" }}>Actions</th>
                </tr>
              </thead>
              <tbody>
                {paginated.map(lead => (
                  <tr key={lead.leadID} className={`tbl-row ${selected?.leadID === lead.leadID ? 'bg-purple-500/10' : ''}`} onClick={() => setSelected(lead)}>
                    <td className="tbl-cell">
                      <div className="text-sm font-bold text-white">{lead.userName}</div>
                      <div className="text-[10px] text-slate-500">{lead.campaignName}</div>
                    </td>
                    <td className="tbl-cell"><span className={statusClass[lead.leadStatus]}>{lead.leadStatus}</span></td>
                    <td className="tbl-cell">
                      <div className={`w-8 h-8 rounded flex items-center justify-center text-[10px] font-bold border ${lead.leadScore > 70 ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : 'bg-slate-500/10 text-slate-400 border-white/10'}`}>
                        {lead.leadScore}
                      </div>
                    </td>
                    <td className="tbl-cell text-right">
                       <button className="btn btn-ghost px-2 py-1 text-xs" onClick={e => { e.stopPropagation(); setEditingLead(lead); setIsEditModalOpen(true); }}>Edit</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="p-4 border-t border-white/5 flex justify-between items-center text-[11px] text-slate-400">
             <div>Page {page} of {totalPages || 1}</div>
             <div className="flex gap-2">
               <button disabled={page === 1} onClick={() => setPage(p => p - 1)} className="btn btn-ghost py-1 px-3">Prev</button>
               <button disabled={page >= totalPages} onClick={() => setPage(p => p + 1)} className="btn btn-ghost py-1 px-3">Next</button>
             </div>
          </div>
        </div>

        {selected && (
          <div className="card w-72 p-6 sticky top-20 anim-slide-right">
            <div className="flex justify-between mb-4">
              <h3 className="text-sm font-bold text-white">Lead Details</h3>
              <button onClick={() => setSelected(null)}>✕</button>
            </div>
            <div className="space-y-4 mb-6">
              <div><small className="block text-[9px] uppercase text-slate-500 tracking-wider">Source</small><div className="text-sm text-slate-200">{selected.source}</div></div>
              <div><small className="block text-[9px] uppercase text-slate-500 tracking-wider">Campaign</small><div className="text-sm text-purple-300">{selected.campaignName}</div></div>
              {selected.notes && <div className="p-3 bg-white/5 rounded-lg text-xs leading-relaxed text-slate-400">{selected.notes}</div>}
            </div>
            <div className="grid grid-cols-2 gap-2 pt-4 border-t border-white/5">
               <button className="btn btn-primary w-full justify-center text-xs" onClick={() => navigate('/email')}>📧 Email</button>
               {isManager && <button className="btn btn-danger-soft w-full justify-center text-xs" onClick={() => handleDelete(selected.leadID)}>Delete</button>}
            </div>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="modal-overlay">
          <div className="modal-box max-w-sm">
            <div className="modal-header"><h2>New Lead</h2><button onClick={() => setIsModalOpen(false)}>✕</button></div>
            <form onSubmit={handleSubmit} className="p-4 space-y-4">
               <div><label className="text-xs text-slate-400">Campaign</label>
               <select className="w-full bg-slate-900 border border-white/10 rounded p-2 text-sm text-white" value={formData.campaignID} onChange={e => setFormData({...formData, campaignID: parseInt(e.target.value)})}>
                 {campaigns.map(c => <option key={c.campaignID} value={c.campaignID}>{c.campaignName}</option>)}
               </select></div>
               <button type="submit" className="btn btn-primary w-full" disabled={isSubmitting}>{isSubmitting ? 'Creating...' : 'Create'}</button>
            </form>
          </div>
        </div>
      )}

      {isEditModalOpen && editingLead && (
        <div className="modal-overlay">
          <div className="modal-box max-w-sm">
            <div className="modal-header"><h2>Edit Lead</h2><button onClick={() => setIsEditModalOpen(false)}>✕</button></div>
            <form onSubmit={handleUpdate} className="p-4 space-y-4">
               <div><label className="text-xs text-slate-400">Status</label>
               <select className="w-full bg-slate-900 border border-white/10 rounded p-2 text-sm text-white" value={editingLead.leadStatus} onChange={e => setEditingLead({...editingLead, leadStatus: e.target.value})}>
                 {['New', 'Contacted', 'Qualified', 'Converted', 'Lost'].map(s => <option key={s} value={s}>{s}</option>)}
               </select></div>
               <div><label className="text-xs text-slate-400">Score</label>
               <input type="number" className="w-full bg-slate-900 border border-white/10 rounded p-2 text-sm text-white" value={editingLead.leadScore} onChange={e => setEditingLead({...editingLead, leadScore: parseInt(e.target.value)})} /></div>
               <button type="submit" className="btn btn-primary w-full" disabled={isSubmitting}>{isSubmitting ? 'Updating...' : 'Save'}</button>
            </form>
          </div>
        </div>
      )}
    </MainLayout>
  );
};

export default Leads;

