import React, { useState, useEffect } from 'react';
import MainLayout from '../../components/layout/MainLayout';
import locationService from '../../services/locationService';
import type { LocationDTO } from '../../services/locationService';
import MapboxMap from '../../components/common/MapboxMap';

const Locations: React.FC = () => {
  const [locations, setLocations] = useState<LocationDTO[]>([]);
  const [search, setSearch] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Omit<LocationDTO, 'locationID'>>({
    locationName: '', latitude: 0, longitude: 0
  });

  useEffect(() => { fetchLocations(); }, []);

  const fetchLocations = async () => {
    try { setLocations(await locationService.getLocations()); } catch (_) { console.error("Error occurred"); }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await locationService.createLocation(formData);
      setIsModalOpen(false);
      fetchLocations();
    } catch (_) { console.error("Error fetching data"); }
  };

  const filtered = locations.filter(l => l.locationName.toLowerCase().includes(search.toLowerCase()));

  return (
    <MainLayout>
      <div className="page-header anim-slide-up">
        <div className="page-header-left">
          <div className="eyebrow">Inventory</div>
          <h1>Locations</h1>
          <p>Manage destinations for your travel campaigns.</p>
        </div>
        <button className="btn btn-primary" onClick={() => setIsModalOpen(true)}>+ Add Location</button>
      </div>

      <div className="filter-bar anim-fade-in">
        <input placeholder="Search locations..." value={search} onChange={e => setSearch(e.target.value)} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1 space-y-4 anim-slide-up delay-1">
          {filtered.map(l => (
            <div key={l.locationID} className="card p-4 hover:border-purple-500/30 transition-all group">
              <div className="flex justify-between items-start">
                 <div>
                   <h3 className="font-bold text-white mb-1">{l.locationName}</h3>
                   <p className="text-[10px] text-slate-500 font-mono italic">{l.latitude.toFixed(4)}, {l.longitude.toFixed(4)}</p>
                 </div>
                 <span className="text-sm opacity-0 group-hover:opacity-100 transition-opacity">📍</span>
              </div>
            </div>
          ))}
        </div>
        
        <div className="lg:col-span-2 min-h-[420px] lg:min-h-[600px] h-full anim-slide-up delay-2">
          <div className="card h-full overflow-hidden relative">
            {filtered.length > 0 ? (
              <MapboxMap 
                lat={filtered[0].latitude} 
                lng={filtered[0].longitude} 
                title={filtered[0].locationName} 
                showRoute={false}
              />
            ) : (
              <div className="w-full h-full flex items-center justify-center bg-slate-900 text-slate-500 italic">Select a location to view on map</div>
            )}
          </div>
        </div>
