                 <div><label className="text-xs text-slate-400">Lng</label>
                 <input type="number" step="any" className="w-full bg-slate-900 border border-white/10 rounded p-2 text-white" value={formData.longitude} onChange={e => setFormData({...formData, longitude: parseFloat(e.target.value)})} required /></div>
               </div>
               <button type="submit" className="btn btn-primary w-full py-3">Create Location</button>
            </form>
          </div>
        </div>
      )}
    </MainLayout>
  );
};

