import React, { useState, useEffect } from 'react';
import MainLayout from '../../components/layout/MainLayout';
import { useAuth } from '../../context/AuthContext';
import customerPortalService from '../../services/customerPortalService';
import type { CampaignOfferDTO, CustomerProfileDTO, CampaignFeedbackDTO } from '../../services/customerPortalService';
import MapboxMap from '../../components/common/MapboxMap';

const CATEGORY_ICONS: Record<string, string> = {
  Luxury: '💎',
  Cultural: '🏛️',
  Tropical: '🌴',
  Adventure: '🏔️',
};

const CustomerPortal: React.FC = () => {
  useAuth();
  const [offers, setOffers] = useState<CampaignOfferDTO[]>([]);
  const [profile, setProfile] = useState<CustomerProfileDTO>({ firstName: '', lastName: '', email: '', phoneNumber: '' });
  const [prefs, setPrefs] = useState({ subscribeLuxury: true, subscribeCultural: true, subscribeTropical: false, subscribeAdventure: false });
  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [activeFeedback, setActiveFeedback] = useState<CampaignOfferDTO | null>(null);
  const [feedback, setFeedback] = useState<CampaignFeedbackDTO>({ campaignID: 0, rating: 5 });
  const [profileSaved, setProfileSaved] = useState(false);

  useEffect(() => { fetchData(); }, []);

  const fetchData = async () => {
    try {
      const [offerData, profileData] = await Promise.all([
        customerPortalService.getOffers(),
        customerPortalService.getProfile(),
      ]);
      setOffers(offerData);
      setProfile(profileData);
    } catch (_) { console.error("Failed to fetch portal data"); }
  };

  const handleProfileSave = async (e: React.FormEvent) => {
    e.preventDefault();
    await customerPortalService.updateProfile(profile);
    setProfileSaved(true);
    setTimeout(() => setProfileSaved(false), 2500);
  };

  const openFeedback = (offer: CampaignOfferDTO) => {
    setActiveFeedback(offer);
    setFeedback({ campaignID: offer.campaignID, rating: 5 });
    setIsFeedbackOpen(true);
  };

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    await customerPortalService.submitFeedback(feedback);
    setIsFeedbackOpen(false);
  };

  const enrolled = offers.filter(o => o.isEnrolled);

  return (
    <MainLayout>
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-slate-100">✈️ Travel Portal</h1>
        <p className="text-slate-400 mt-1">Discover personalized travel experiences curated just for you.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main Column */}
        <div className="lg:col-span-2 space-y-8">

          {/* Campaign Offers Grid */}
          <section>
            <h2 className="text-xl font-bold text-slate-200 mb-4">🌟 Exclusive Campaign Offers</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              {offers.map(offer => (
                <div key={offer.campaignID} className="glass-card overflow-hidden border-white/5 group hover:border-purple-500/30 transition-all">
                  {/* Destination image (gradient placeholder with flag) */}
                  <div className="h-36 relative overflow-hidden" style={{
                    background: 'linear-gradient(135deg, #1a1f37 0%, #0d1124 100%)'
                  }}>
                    <div className="absolute inset-0 flex flex-col items-center justify-center">
                      <span className="text-5xl mb-2">
                        {offer.country === 'Greece' ? '🇬🇷' : offer.country === 'Japan' ? '🇯🇵' : offer.country === 'Indonesia' ? '🇮🇩' : offer.country === 'Philippines' ? '🇵🇭' : '🌍'}
                      </span>
                      <span className="text-xs text-slate-400">{offer.locationName}</span>
                    </div>
                    <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent" />
                    {offer.isEnrolled && (
                      <div className="absolute top-3 right-3 bg-emerald-500/20 border border-emerald-500/40 text-emerald-400 text-[10px] font-bold px-2 py-0.5 rounded-full">
                        ENROLLED
                      </div>
                    )}
                  </div>
                  <div className="p-5">
                    <h3 className="text-white font-bold mb-1">{offer.campaignName}</h3>
                    <p className="text-xs text-slate-400 mb-4 line-clamp-2">{offer.description ?? 'Exclusive travel experience awaits.'}</p>
                    <div className="flex items-center justify-between text-xs text-slate-500 mb-4">
                      <span>📅 {new Date(offer.startDate).toLocaleDateString()} – {new Date(offer.endDate).toLocaleDateString()}</span>
                    </div>
                    <div className="flex gap-2">
                      {!offer.isEnrolled && (
                        <button className="flex-1 py-2 btn-gradient text-white text-xs font-semibold rounded-lg hover:scale-[1.02] transition-all">
                          Enroll Now
                        </button>
                      )}
                      <button
                        onClick={() => openFeedback(offer)}
                        className="flex-1 py-2 bg-white/5 hover:bg-white/10 border border-white/10 text-slate-300 text-xs font-semibold rounded-lg transition-all"
                      >
                        💬 Feedback
                      </button>
                    </div>
                  </div>
                </div>
              ))}
              {offers.length === 0 && (
                <div className="md:col-span-2 glass-card p-12 text-center text-slate-500 italic">No active campaign offers.</div>
              )}
            </div>
          </section>

          {/* Map Section */}
          <section>
            <h2 className="text-xl font-bold text-slate-200 mb-4">🗺️ Destination Tracker</h2>
            <div className="card h-[280px] sm:h-[340px] lg:h-[400px] overflow-hidden">
               {offers.length > 0 && offers[0].latitude ? (
                 <MapboxMap 
                    lat={Number(offers[0].latitude)} 
                    lng={Number(offers[0].longitude)} 
                    title={offers[0].locationName || 'Travel Destination'} 
                    description={offers[0].description}
                    showRoute={true}
                 />
               ) : (
                 <div className="w-full h-full flex flex-col items-center justify-center bg-slate-900 text-slate-500 italic">
                   <span className="text-4xl mb-4">🗺️</span>
                   Enroll in a campaign to see your journey route.
                 </div>
               )}
            </div>
          </section>

          {/* My Campaigns */}
          <section>
            <h2 className="text-xl font-bold text-slate-200 mb-4">📋 My Campaigns</h2>
            <div className="glass-card overflow-hidden border-white/5">
              {enrolled.length > 0 ? (
                <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
                    <tr className="border-b border-white/5 text-[10px] font-bold text-slate-500 uppercase tracking-widest">
                      <th className="px-6 py-4">Campaign</th>
                      <th className="px-6 py-4">Destination</th>
                      <th className="px-6 py-4 text-right">Ends</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-white/5">
                    {enrolled.map(o => (
                      <tr key={o.campaignID} className="hover:bg-white/5">
                        <td className="px-6 py-4 text-slate-200 font-medium">{o.campaignName}</td>
                        <td className="px-6 py-4 text-sm text-slate-400">{o.locationName ?? '—'}</td>
                        <td className="px-6 py-4 text-xs text-slate-500 text-right">{new Date(o.endDate).toLocaleDateString()}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                </div>
              ) : (
                <div className="py-10 text-center text-slate-500 italic">You have not enrolled in any campaigns yet.</div>
              )}
            </div>
          </section>
        </div>

        {/* Sidebar Column */}
        <div className="space-y-6">
          {/* Profile Settings */}
          <div className="glass-card p-6 border-white/5">
            <h2 className="text-lg font-bold text-white mb-5">👤 Profile Settings</h2>
            <form onSubmit={handleProfileSave} className="space-y-4">
              <div>
                <label className="block text-xs font-medium text-slate-400 mb-1.5">First Name</label>
                <input className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-white text-sm" value={profile.firstName} onChange={e => setProfile(p => ({ ...p, firstName: e.target.value }))} />
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-400 mb-1.5">Last Name</label>
                <input className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-white text-sm" value={profile.lastName} onChange={e => setProfile(p => ({ ...p, lastName: e.target.value }))} />
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-400 mb-1.5">Email</label>
                <input readOnly className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-slate-500 text-sm cursor-not-allowed" value={profile.email} />
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-400 mb-1.5">Phone Number</label>
                <input className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-white text-sm" value={profile.phoneNumber} onChange={e => setProfile(p => ({ ...p, phoneNumber: e.target.value }))} placeholder="+1 (555) 000-0000" />
              </div>
              <button type="submit" className={`w-full py-2.5 rounded-xl font-semibold text-sm transition-all ${profileSaved ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30' : 'btn-gradient text-white shadow-lg shadow-purple-500/20'}`}>
                {profileSaved ? '✓ Saved!' : 'Save Changes'}
              </button>
            </form>
          </div>

          {/* Email Subscription Toggles */}
          <div className="glass-card p-6 border-white/5">
            <h2 className="text-lg font-bold text-white mb-5">📧 Campaign Subscriptions</h2>
            <div className="space-y-4">
              {(Object.keys(CATEGORY_ICONS) as (keyof typeof CATEGORY_ICONS)[]).map(cat => {
                const key = `subscribe${cat}` as keyof typeof prefs;
                return (
                  <div key={cat} className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <span className="text-xl">{CATEGORY_ICONS[cat]}</span>
                      <div>
                        <p className="text-sm font-medium text-slate-200">{cat} Travel</p>
                        <p className="text-xs text-slate-500">Receive {cat.toLowerCase()} deals</p>
                      </div>
                    </div>
                    <button
                      onClick={() => setPrefs(p => ({ ...p, [key]: !p[key] }))}
                      className={`w-11 h-6 rounded-full p-0.5 transition-colors relative ${prefs[key] ? 'bg-purple-500 shadow-[0_0_10px_rgba(168,85,247,0.4)]' : 'bg-slate-700'}`}
                    >
                      <div className={`w-5 h-5 bg-white rounded-full transition-transform ${prefs[key] ? 'translate-x-5' : 'translate-x-0'}`} />
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>

      {/* Feedback Modal */}
      {isFeedbackOpen && activeFeedback && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="glass-card w-full max-w-md p-8 shadow-2xl border-white/20">
            <h2 className="text-xl font-bold text-white mb-1">Campaign Feedback</h2>
            <p className="text-slate-400 text-sm mb-6">{activeFeedback.campaignName}</p>
            <form onSubmit={submitFeedback} className="space-y-5">
              <div>
                <label className="block text-sm font-medium text-slate-300 mb-3">Rating</label>
                <div className="flex gap-2">
                  {[1, 2, 3, 4, 5].map(star => (
                    <button
                      key={star}
                      type="button"
                      onClick={() => setFeedback(f => ({ ...f, rating: star }))}
                      className={`text-2xl transition-all ${star <= feedback.rating ? 'scale-110' : 'opacity-30'}`}
                    >
                      ⭐
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-300 mb-2">Comment</label>
                <textarea className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white h-28 text-sm" placeholder="Share your experience..." onChange={e => setFeedback(f => ({ ...f, comment: e.target.value }))} />
              </div>
              <div className="flex flex-col sm:flex-row justify-end gap-3">
                <button type="button" onClick={() => setIsFeedbackOpen(false)} className="px-5 py-2.5 bg-white/5 text-slate-300 rounded-xl border border-white/10 text-sm font-semibold">Cancel</button>
                <button type="submit" className="px-7 py-2.5 btn-gradient text-white rounded-xl text-sm font-semibold shadow-lg shadow-purple-500/20">Submit</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </MainLayout>
  );
};

export default CustomerPortal;

import React, { useState, useEffect } from 'react';
import MainLayout from '../../components/layout/MainLayout';
import { useAuth } from '../../context/AuthContext';
import automationService from '../../services/automationService';
import type { IntegrationSettingsDTO } from '../../services/automationService';

const Settings: React.FC = () => {
  const { user } = useAuth();
  const [settings, setSettings] = useState<IntegrationSettingsDTO>({
    mapboxAccessToken: '',
    emailSmtpHost: '',
    emailSmtpPort: 587,
    emailSender: ''
  });
  const [isSaving, setIsSaving] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'success' | 'error'>('idle');

  const isSuperAdmin = user?.role === 'SuperAdmin';

  useEffect(() => {
    if (isSuperAdmin) {
      fetchSettings();
    }
  }, [isSuperAdmin]);

  const fetchSettings = async () => {
    try {
      const data = await automationService.getSettings();
      setSettings(data);
    } catch (e) {
      console.error('Failed to fetch settings:', e);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    setSaveStatus('idle');
    try {
      // In a real app, we'd have a specific updateSettings endpoint
      // For now, we'll simulate a successful save
      await new Promise(resolve => setTimeout(resolve, 1000));
      setSaveStatus('success');
      setTimeout(() => setSaveStatus('idle'), 3000);
    } catch (_) {
      setSaveStatus('error');
    } finally {
      setIsSaving(false);
    }
  };

  if (!isSuperAdmin) {
    return (
      <MainLayout>
        <div className="flex items-center justify-center min-h-[60vh]">
          <div className="card p-12 text-center max-w-md">
            <div className="text-4xl mb-4">🛡️</div>
            <h2 className="text-xl font-bold text-white mb-2">Access Restricted</h2>
            <p className="text-slate-400">This page is only accessible to SuperAdmins. Please contact your system administrator for assistance.</p>
          </div>
        </div>
      </MainLayout>
    );
  }

  return (
    <MainLayout>
      <div className="page-header anim-slide-up">
        <div className="page-header-left">
          <div className="eyebrow">Administration</div>
          <h1>System Settings</h1>
          <p>Configure global integrations and security parameters.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 anim-slide-up delay-1">
        {/* API Integrations */}
        <div className="card p-6 border-white/5">
          <h2 className="text-lg font-bold text-white mb-6">🌐 API Integrations</h2>
          <form onSubmit={handleSave} className="space-y-6">
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-widest mb-2">Mapbox Access Token</label>
                <div className="relative">
                  <input 
                    type="password"
                    className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm font-mono focus:border-purple-500/50 transition-all" 
                    value={settings.mapboxAccessToken}
                    onChange={e => setSettings({...settings, mapboxAccessToken: e.target.value})}
                    placeholder="Enter Access Token"
                  />
                  <div className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-bold text-emerald-400 bg-emerald-400/10 px-2 py-0.5 rounded border border-emerald-400/20">CONNECTED</div>
                </div>
                <p className="mt-2 text-[10px] text-slate-500">Required for dynamic routing and high-fidelity dark-themed map tiles.</p>
              </div>

              <div className="pt-4 border-t border-white/5">
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-widest mb-4">Email Service (SMTP)</label>
                <div className="grid grid-cols-2 gap-4 mb-4">
                  <div>
                    <label className="block text-[10px] font-bold text-slate-400 mb-1.5 ml-1">SMTP Host</label>
                    <input 
                      className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-white text-sm" 
                      value={settings.emailSmtpHost}
                      onChange={e => setSettings({...settings, emailSmtpHost: e.target.value})}
                      placeholder="smtp.gmail.com"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-400 mb-1.5 ml-1">Port</label>
                    <input 
                      type="number"
                      className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-white text-sm" 
                      value={settings.emailSmtpPort}
                      onChange={e => setSettings({...settings, emailSmtpPort: parseInt(e.target.value) || 587})}
                      placeholder="587"
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-400 mb-1.5 ml-1">Verified Sender Address</label>
                  <input 
                    className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-white text-sm" 
                    value={settings.emailSender}
                    onChange={e => setSettings({...settings, emailSender: e.target.value})}
                    placeholder="noreply@voyager-travel.com"
                  />
                </div>
              </div>
            </div>

            <div className="flex items-center justify-between pt-4">
              <div className="text-[11px] text-slate-500 italic max-w-[200px]">
                {saveStatus === 'success' && <span className="text-emerald-400 font-bold">✓ Settings updated successfully</span>}
                {saveStatus === 'error' && <span className="text-red-400 font-bold">⚠ Failed to save settings</span>}
              </div>
              <button 
                type="submit" 
                disabled={isSaving}
                className="px-8 py-3 btn-gradient text-white font-bold rounded-xl shadow-lg shadow-purple-500/20 hover:scale-[1.02] active:scale-[0.98] transition-all disabled:opacity-50"
              >
                {isSaving ? 'Saving...' : 'Save Configuration'}
              </button>
            </div>
          </form>
        </div>

        {/* System Management & Security */}
        <div className="space-y-8">
          <div className="card p-6 border-white/5">
            <h2 className="text-lg font-bold text-white mb-6">🛡️ Maintenance & Security</h2>
            <div className="space-y-6">
              <div className="p-4 bg-white/5 rounded-2xl border border-white/5">
                <div className="flex justify-between items-center mb-4">
                  <div>
                    <h3 className="text-sm font-bold text-slate-200">Database Backup</h3>
                    <p className="text-[10px] text-slate-500">Download a full snapshot of the Voyager database.</p>
                  </div>
                  <button className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-bold rounded-lg transition-all">Generate Backup</button>
                </div>
                <div className="text-[10px] text-slate-600 flex items-center gap-2">
                  <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full"></span>
                  Last backup: 24h ago (1.4 GB)
                </div>
              </div>

              <div className="p-4 bg-red-500/5 rounded-2xl border border-red-500/10">
                <h3 className="text-sm font-bold text-red-100">Security Override</h3>
                <p className="text-[10px] text-red-400/70 mb-4">Danger Zone: Bypassing standard security settings can lead to data exposure.</p>
                <div className="flex items-center justify-between mb-4">
                  <span className="text-xs text-slate-300">Allow Cross-Origin Scripting (CORS Override)</span>
                  <button className="w-10 h-5 bg-slate-800 rounded-full p-0.5 relative">
                    <div className="w-4 h-4 bg-slate-600 rounded-full shadow-md"></div>
                  </button>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-xs text-slate-300">Bypass Role-Based Access for Admins</span>
                  <button className="w-10 h-5 bg-slate-800 rounded-full p-0.5 relative">
                    <div className="w-4 h-4 bg-slate-600 rounded-full shadow-md"></div>
                  </button>
                </div>
              </div>
            </div>
          </div>

          <div className="card p-6 border-white/5 bg-gradient-to-br from-purple-500/5 to-transparent">
            <h2 className="text-lg font-bold text-white mb-2">⚙️ System Audit Logs</h2>
            <p className="text-xs text-slate-500 mb-6">Track all sensitive administrative actions across the platform.</p>
            <div className="space-y-3">
              {[
                { action: 'SuperAdmin updated Mapbox Token', time: '1h ago', user: 'admin@voyager.com' },
                { action: 'Admin modified role for Janine', time: '5h ago', user: 'admin@voyager.com' },
                { action: 'Backup generated successfully', time: '24h ago', user: 'System' }
              ].map((log, i) => (
                <div key={i} className="flex justify-between items-center text-[11px] py-2 border-b border-white/5 last:border-0">
                  <div className="flex flex-col">
                    <span className="text-slate-300 font-medium">{log.action}</span>
                    <span className="text-slate-600">{log.user}</span>
                  </div>
                  <span className="text-slate-600">{log.time}</span>
                </div>
              ))}
            </div>
            <button className="w-full mt-6 py-2.5 bg-white/5 hover:bg-white/10 border border-white/10 rounded-xl text-xs font-bold text-slate-300 transition-all">View Full Audit Trail</button>
          </div>
        </div>
      </div>
    </MainLayout>
  );
};

export default Settings;

import React, { useState, useEffect } from 'react';
import MainLayout from '../../components/layout/MainLayout';
import { useAuth } from '../../context/AuthContext';
import userService from '../../services/userService';
import type { UserDTO, CreateUserDTO, AuditLogDTO } from '../../services/userService';

// Roles an Admin can assign and see
const ADMIN_ROLES = ['Marketing Manager', 'Marketing Staff', 'Customer'];
// Roles only a SuperAdmin can assign or see
const SUPER_ADMIN_ROLES = ['Admin', 'SuperAdmin'];
const PROTECTED_ROLES = new Set(['Admin', 'SuperAdmin']);


const roleColor: Record<string, string> = {
  SuperAdmin: 'bg-purple-500/20 text-purple-300',
  Admin: 'bg-blue-500/20 text-blue-300',
  'Marketing Manager': 'bg-violet-500/20 text-violet-300',
  'Marketing Staff': 'bg-slate-500/20 text-slate-300',
  Customer: 'bg-teal-500/20 text-teal-300',
};

const Users: React.FC = () => {
  const { user } = useAuth();
  const [users, setUsers] = useState<UserDTO[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLogDTO[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [search, setSearch] = useState('');
  const [roleFilter, setRoleFilter] = useState('');
  const [sortKey, setSortKey] = useState<keyof UserDTO>('lastName');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('asc');
  const [page, setPage] = useState(1);
  const pageSize = 5;

  const isSuperAdmin = user?.role === 'SuperAdmin';
  const isAdmin = user?.role === 'Admin';

  // Roles this user is allowed to assign
  const assignableRoles = isSuperAdmin ? [...ADMIN_ROLES, 'Admin'] : ADMIN_ROLES;

  const [formData, setFormData] = useState<CreateUserDTO>({
    userName: '', email: '', firstName: '', lastName: '', role: 'Marketing Staff', password: ''
  });

  // Can this user interact with the given row?
  const canEditRow = (u: UserDTO) => {
    if (isSuperAdmin) return u.role !== 'SuperAdmin'; // SuperAdmin can edit everyone except other SuperAdmins
    if (isAdmin) return !PROTECTED_ROLES.has(u.role);  // Admin cannot touch Admin/SuperAdmin rows
    return false;
  };

  useEffect(() => { fetchData(); }, []);

  const fetchData = async () => {
    try {
      const data = await userService.getUsers();
      setUsers(data);
      if (isSuperAdmin) {
        const logs = await userService.getAuditLogs();
        setAuditLogs(logs);
      }
    } catch (_) { console.error("Error fetching data"); }
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      await userService.createUser(formData);
      setIsModalOpen(false);
      setFormData({ userName: '', email: '', firstName: '', lastName: '', role: 'Marketing Staff', password: '' });
      fetchData();
    } catch (_) { console.error("Error fetching data"); }
    finally { setIsSubmitting(false); }
  };

  const toggleStatus = async (u: UserDTO) => {
    const next = u.accountStatus === 'Active' ? 'Suspended' : 'Active';
    await userService.updateStatus(u.id, next);
    fetchData();
  };

  const handleRoleChange = async (id: number, role: string) => {
    await userService.updateRole(id, role);
    fetchData();
  };

  const sorted = users
    .filter(u => {
      const matchSearch = `${u.firstName} ${u.lastName} ${u.email}`.toLowerCase().includes(search.toLowerCase());
      const matchRole = roleFilter ? u.role === roleFilter : true;
      return matchSearch && matchRole;
    })
    .sort((a, b) => {
      const valA = a[sortKey];
      const valB = b[sortKey];
      if (valA === undefined || valB === undefined) return 0;
      if (valA < valB) return sortOrder === 'asc' ? -1 : 1;
      if (valA > valB) return sortOrder === 'asc' ? 1 : -1;
      return 0;
    });

  const paginated = sorted.slice((page - 1) * pageSize, page * pageSize);
  const totalPages = Math.ceil(sorted.length / pageSize);

  // Filter dropdown options based on viewer role
  const filterRoleOptions = isSuperAdmin
    ? [...ADMIN_ROLES, ...SUPER_ADMIN_ROLES]
    : ADMIN_ROLES;

  return (
    <MainLayout>
      {/* Header */}
      <div className="page-header anim-slide-up">
        <div className="page-header-left">
          <div className="eyebrow">Admin</div>
          <h1>User Management</h1>
          <p>Manage accounts, roles, and access across the system.</p>
        </div>
        <button className="btn btn-primary" onClick={() => setIsModalOpen(true)}>+ Add User</button>
      </div>

      {/* Filters */}
      <div className="filter-bar anim-fade-in">
        <input
          type="text"
          placeholder="Search by name or email…"
          value={search}
          onChange={e => setSearch(e.target.value)}
        />
        <select value={roleFilter} onChange={e => setRoleFilter(e.target.value)}>
          <option value="" className="bg-slate-900">All Roles</option>
          {filterRoleOptions.map(r => <option key={r} value={r} className="bg-slate-900">{r}</option>)}
        </select>
      </div>

      {/* Users Table */}
      <div className="card overflow-hidden anim-slide-up delay-1" style={{ marginBottom: "22px" }}>
        <div className="tbl-header">
          <span>All Users</span>
          <small>{sorted.length} matches</small>
        </div>
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr className="tbl-head-row">
                <th className="tbl-cell cursor-pointer hover:text-purple-300" onClick={() => { setSortKey('lastName'); setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc'); }}>User</th>
                <th className="tbl-cell cursor-pointer hover:text-purple-300" onClick={() => { setSortKey('email'); setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc'); }}>Email</th>
                <th className="tbl-cell cursor-pointer hover:text-purple-300" onClick={() => { setSortKey('role'); setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc'); }}>Role</th>
                <th className="tbl-cell">Status</th>
                <th className="tbl-cell">Joined</th>
                <th className="tbl-cell" style={{ textAlign: "right" }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {paginated.map(u => (
                <tr key={u.id} className="tbl-row">
                  <td className="tbl-cell">
                    <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                      <div style={{
                        width: "32px", height: "32px", borderRadius: "50%", flexShrink: 0,
                        background: "var(--gradient)",
                        display: "flex", alignItems: "center", justifyContent: "center",
                        fontSize: "11px", fontWeight: "700", color: "white"
                      }}>{u.firstName?.[0]}{u.lastName?.[0]}</div>
                      <div>
                        <div style={{ fontSize: "13px", fontWeight: "600", color: "var(--text-primary)" }}>{u.firstName} {u.lastName}</div>
                        <div style={{ fontSize: "10px", color: "var(--text-muted)" }}>@{u.userName}</div>
                      </div>
                    </div>
                  </td>
                  <td className="tbl-cell" style={{ fontSize: "12px", color: "var(--text-secondary)" }}>{u.email}</td>
                  <td className="tbl-cell">
                    {canEditRow(u) ? (
                      <select
                        value={u.role}
                        onChange={e => handleRoleChange(u.id, e.target.value)}
                        className={`text-xs font-semibold px-3 py-1.5 rounded-full border-0 cursor-pointer ${roleColor[u.role] ?? 'bg-slate-500/20 text-slate-300'}`}
                        style={{ fontFamily: 'inherit' }}
                      >
                        {assignableRoles.map(r => <option key={r} value={r} className="bg-slate-900">{r}</option>)}
                      </select>
                    ) : (
                      <span className={`text-xs font-semibold px-3 py-1.5 rounded-full ${roleColor[u.role] ?? 'bg-slate-500/20 text-slate-300'}`}>
                        {u.role}
                      </span>
                    )}
                  </td>
                  <td className="tbl-cell">
                    <span className={u.accountStatus === 'Active' ? 'badge badge-green' : u.accountStatus === 'Suspended' ? 'badge badge-red' : 'badge badge-gray'}>
                      {u.accountStatus}
                    </span>
                  </td>
                  <td className="tbl-cell" style={{ fontSize: "11px", color: "var(--text-muted)" }}>{new Date(u.createdDate).toLocaleDateString()}</td>
                  <td className="tbl-cell" style={{ textAlign: "right" }}>
                    {canEditRow(u) ? (
                      <button
                        onClick={() => toggleStatus(u)}
                        className={u.accountStatus === 'Active' ? 'btn btn-danger' : 'btn btn-ghost'}
                        style={{ padding: "5px 12px", fontSize: "11px" }}
                      >
                        {u.accountStatus === 'Active' ? 'Suspend' : 'Activate'}
                      </button>
                    ) : (
                      <span style={{ fontSize: "11px", color: "var(--text-muted)", fontStyle: "italic" }}>Protected</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          
          {/* Pagination */}
          <div className="p-4 border-t border-white/5 flex flex-col sm:flex-row gap-3 sm:gap-0 justify-between sm:items-center text-xs text-slate-400">
            <div>Page {page} of {totalPages || 1}</div>
            <div className="flex gap-2">
              <button disabled={page === 1} onClick={() => setPage(p => p - 1)} className="btn btn-ghost px-3 py-1">Previous</button>
              <button disabled={page === totalPages || totalPages === 0} onClick={() => setPage(p => p + 1)} className="btn btn-ghost px-3 py-1">Next</button>
            </div>
          </div>

          {sorted.length === 0 && (
            <div className="empty-state">
              <div className="empty-icon">👤</div>
              <h3>No users found</h3>
              <p>Adjust your filters or add a new user.</p>
            </div>
          )}
        </div>
      </div>

      {/* Audit Log — Super Admin only */}
      {isSuperAdmin && (
        <div className="glass-card overflow-hidden">
          <div className="px-6 py-4 border-b border-white/5 flex items-center gap-3">
            <span className="text-lg">🛡️</span>
            <h2 className="text-lg font-bold text-white">System Audit Log</h2>
            <span className="text-xs bg-purple-500/20 text-purple-300 px-2 py-0.5 rounded-full">Super Admin Only</span>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="border-b border-white/5 text-[10px] font-bold text-slate-500 uppercase tracking-widest">
                  <th className="px-6 py-4">User</th>
                  <th className="px-6 py-4">Action</th>
                  <th className="px-6 py-4">Module</th>
                  <th className="px-6 py-4">Details</th>
                  <th className="px-6 py-4 text-right">Timestamp</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                {auditLogs.map(log => (
                  <tr key={log.id} className="hover:bg-white/5">
                    <td className="px-6 py-3 text-sm text-purple-300 font-medium">@{log.userName}</td>
                    <td className="px-6 py-3">
                      <span className="text-xs bg-blue-500/10 text-blue-300 px-2 py-1 rounded-md">{log.action}</span>
                    </td>
                    <td className="px-6 py-3 text-xs text-slate-400">{log.module}</td>
                    <td className="px-6 py-3 text-xs text-slate-500 max-w-xs truncate">{log.details}</td>
                    <td className="px-6 py-3 text-xs text-slate-500 text-right">
                      {new Date(log.timestamp).toLocaleString()}
                    </td>
                  </tr>
                ))}
                {auditLogs.length === 0 && (
                  <tr><td colSpan={5} className="py-10 text-center text-slate-600 italic">No audit entries yet.</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Add User Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="glass-card w-full max-w-lg p-8 shadow-2xl border-white/20">
            <h2 className="text-2xl font-bold text-white mb-6">Add New User</h2>
            <form onSubmit={handleCreate} className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-300 mb-2">First Name</label>
                  <input required className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-white" value={formData.firstName} onChange={e => setFormData(f => ({ ...f, firstName: e.target.value }))} />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-300 mb-2">Last Name</label>
                  <input required className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-white" value={formData.lastName} onChange={e => setFormData(f => ({ ...f, lastName: e.target.value }))} />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-300 mb-2">Username</label>
                <input required className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-white" value={formData.userName} onChange={e => setFormData(f => ({ ...f, userName: e.target.value }))} />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-300 mb-2">Email</label>
                <input required type="email" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-white" value={formData.email} onChange={e => setFormData(f => ({ ...f, email: e.target.value }))} />
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-300 mb-2">Role</label>
                  <select required className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-white" value={formData.role} onChange={e => setFormData(f => ({ ...f, role: e.target.value }))}>
                    {assignableRoles.map(r => <option key={r} value={r} className="bg-slate-900">{r}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-300 mb-2">Password</label>
                  <input required type="password" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2.5 text-white" value={formData.password} onChange={e => setFormData(f => ({ ...f, password: e.target.value }))} />
                </div>
              </div>
              <div className="flex flex-col sm:flex-row justify-end gap-3 mt-2">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-6 py-2.5 bg-white/5 text-slate-300 rounded-xl border border-white/10 font-semibold">Cancel</button>
                <button type="submit" disabled={isSubmitting} className="px-8 py-2.5 btn-gradient text-white rounded-xl font-semibold shadow-lg shadow-purple-500/20 disabled:opacity-50">
                  {isSubmitting ? 'Creating...' : 'Create User'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </MainLayout>
  );
};

export default Users;

import axios from 'axios';

const api = axios.create({
  baseURL: '/api', // Vite proxy handles this in development
  headers: {
    'Content-Type': 'application/json',
  },
});

// Add a request interceptor to include the JWT token in headers
api.interceptors.request.use(
  (config) => {
    const savedUser = localStorage.getItem('voyager_user');
    if (savedUser) {
      try {
        const { token } = JSON.parse(savedUser);
        if (token) {
          config.headers.Authorization = `Bearer ${token}`;
        }
      } catch (e) {
        // Silently fail if JSON is malformed
      }
    }
    return config;
  },
  (error) => Promise.reject(error)
);

export default api;
